use std::io::{self, Read};

const PRIME_COUNT: usize = 35;
const PRIME_BITS: usize = 29;
const ROW_BOUND_BITS: usize = 10;
// the 35 smallest primes above 10^9, between 2^29 and 2^30; generated by 1914_matrix_table.py
const PRIMES: [u64; PRIME_COUNT] = [
    1000000007, 1000000009, 1000000021, 1000000033, 1000000087, 1000000093, 1000000097, 1000000103,
    1000000123, 1000000181, 1000000207, 1000000223, 1000000241, 1000000271, 1000000289, 1000000297,
    1000000321, 1000000349, 1000000363, 1000000403, 1000000409, 1000000411, 1000000427, 1000000433,
    1000000439, 1000000447, 1000000453, 1000000459, 1000000483, 1000000513, 1000000531, 1000000579,
    1000000607, 1000000613, 1000000637,
];

fn power(mut value: u64, mut exponent: u64, modulus: u64) -> u64 {
    let mut result = 1;
    while exponent > 0 {
        if exponent & 1 != 0 {
            result = result * value % modulus;
        }
        value = value * value % modulus;
        exponent >>= 1;
    }
    result
}

fn determinant_modulo(matrix: &[Vec<i64>], modulus: u64) -> u64 {
    let size = matrix.len();
    let signed = modulus as i64;
    let mut values: Vec<Vec<u64>> = matrix
        .iter()
        .map(|row| {
            row.iter()
                .map(|&value| ((value % signed + signed) % signed) as u64)
                .collect()
        })
        .collect();
    let mut determinant = 1;
    for column in 0..size {
        let pivot = (column..size).find(|&row| values[row][column] != 0);
        let Some(pivot) = pivot else { return 0 };
        if pivot != column {
            values.swap(pivot, column);
            determinant = modulus - determinant;
        }
        let pivot_value = values[column][column];
        determinant = determinant * pivot_value % modulus;
        let inverse = power(pivot_value, modulus - 2, modulus);
        let (front, back) = values.split_at_mut(column + 1);
        let pivot_line = &front[column];
        for line in back {
            if line[column] == 0 {
                continue;
            }
            let factor = line[column] * inverse % modulus;
            for target in column + 1..size {
                let product = factor * pivot_line[target] % modulus;
                line[target] = if line[target] >= product {
                    line[target] - product
                } else {
                    line[target] + modulus - product
                };
            }
            line[column] = 0;
        }
    }
    determinant
}

fn is_unimodular(matrix: &[Vec<i64>]) -> bool {
    let needed = (ROW_BOUND_BITS * matrix.len() + PRIME_BITS) / PRIME_BITS;
    let mut sign = 0;
    for &modulus in &PRIMES[..needed] {
        let determinant = determinant_modulo(matrix, modulus);
        let current = if determinant == 1 {
            1
        } else if determinant == modulus - 1 {
            -1
        } else {
            0
        };
        if current == 0 || (sign != 0 && sign != current) {
            return false;
        }
        sign = current;
    }
    true
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();
    let mut tokens = text.split_whitespace();
    let size = tokens.next().unwrap().parse::<usize>().unwrap();
    let matrix: Vec<Vec<i64>> = (0..size)
        .map(|_| {
            (0..size)
                .map(|_| tokens.next().unwrap().parse::<i64>().unwrap())
                .collect()
        })
        .collect();
    println!(
        "{}",
        if is_unimodular(&matrix) {
            "Death"
        } else {
            "Power of magic saves lives"
        }
    );
}
